clc; clearvars;
%%
root_dir = "..";
addpath(genpath(fullfile(root_dir,"O3_Lidar/proc_functions/")))
addpath(genpath(fullfile(root_dir,"signal_analysis/functions/")))

data_path = fullfile(root_dir,"O3_processed_data/");

dataFiles = dir(fullfile(data_path, "*.mat"));
fileNames = string(dataFiles.name);

fid = 1;
prof_id = 1;

min_alt = 300;
max_alt = 8e3;

data = load(fullfile(data_path,fileNames(fid)));
%%
t = data.times_avg;
z = data.z_vec';

alt_id = z >= min_alt & z <= max_alt;

z = z(alt_id);
zkm = z.*1e-3;
on = data.mg_on_fr(alt_id,:);
off = data.mg_off_fr(alt_id,:);
qO3 = data.q_o3_mg_merged(alt_id,:);
NO3 = data.N_o3_mg_merged(alt_id,:);
Na = data.Na(alt_id,:);
Ta = data.Ta(alt_id,:);
sigma_o3_on = data.sigma_o3_on(alt_id,:);
sigma_o3_off = data.sigma_o3_off(alt_id,:);
%%
%[text] Produce synthetic profile here
% Ozone Absorption Cross Section
BDM = load("..\signal_analysis\cross_sections\ozone\bdm\bdm_287_299.mat");

% Ozone profile
N_O3 = NO3(:,prof_id);

% Air number density
Nair = Na(:,prof_id);

% On and off wavelengths
lam_on = 287.2e-9;
lam_off = 299.1e-9;

% Ozone absorption cross section
sigma_o3_on = sigma_o3_on(:,prof_id); % use first temp dependent cross section for now
sigma_o3_off = sigma_o3_off(:,prof_id);

% Emitted pulse power at each wavelength
% E0_on = 10.6e-3;
% E0_off = 6.3e-3;
E0_on = 50e-3;
E0_off = 50e-3;

% Efficiency factor at each wavelength
% eta_on = 0.005;
% eta_off = 0.009;
eta_on = 1;
eta_off = 1;

% Detector quantum efficiency
etaQ = 0.7;

% Telescope primary area
t_r = .2;   % Radius of the receiver in meters
o_r = 0.1;  % Radius of the obstruction
A = pi.*(t_r^2 - o_r^2);

% DAQ sampling rate
f = 40e6;
tau = 1/f; % Laser pulse duration

% Overlap function
O = ones(size(z));

gate_alt = 680;
on_sim = signal(z,lam_on,E0_on,A,tau,eta_on,etaQ,Nair,sigma_o3_on,N_O3,O,gate_alt) .*1e-6./tau; 
off_sim = signal(z,lam_off,E0_off,A,tau,eta_off,etaQ,Nair,sigma_o3_off,N_O3,O,gate_alt) .*1e-6./tau; 
%%
on_off = [on(:,prof_id) off(:,prof_id)];
on_off_dispname = ["On" "Off"];
prof_plot(zkm,on_off,[],[],"Altitude (km)","Count Rate (MHz)","",on_off_dispname) %[output:91b4c382]
on_off_sim = [on_sim off_sim];
on_off_sim_dispname = ["On sim " "Off sim"];
prof_plot(zkm,on_off_sim,[],[],"Altitude (km)","Count Rate (MHz)","",on_off_sim_dispname) %[output:1acecd72]
figure; %[output:65f1aa1b]
scatter(on_off, on_off_sim) %[output:65f1aa1b]
prof_plot(zkm,N_O3) %[output:608762f5]
im_plot(t,zkm,on,[],[],"","","MHz","On Signal",12); %[output:4c73e981]
im_plot(t,zkm,off,[],[],"","","MHz","Off Signal",12); %[output:536a761c]
ND_plot(t,zkm,qO3) %[output:39f5fca3]
%%
function im_plot(x,y,z,c_lim,y_lim,x_label,y_label,c_label,title_str,fs)
    figure;
    I = imagesc(x, y, z);
    cbar_tolnet=colorbar_tolnet_func;
    colormap(cbar_tolnet);
    ax = gca;

    set(gca, 'ColorScale', 'log')

    if ~isempty(c_lim)
        ax.CLim = c_lim;
    end

    set(gca,'YDir','normal');
    set(I,'AlphaData',~isnan(z));

    if ~isempty(y_lim)
        ylim(y_lim)
    end
    c = colorbar;
    c.Label.String = c_label;
    xlabel(x_label)
    ylabel(y_label)
    title(title_str)
    fontsize(fs,"points")
end

function prof_plot(x,y,x_lim,y_lim,x_label,y_label,title_str,disp_name)
    arguments
        x 
        y 
        x_lim       = []
        y_lim       = []
        x_label     = []
        y_label     = []
        title_str   = []
        disp_name   = []
    end

    n_prof = size(y,2);

    figure;
    hold on
    for i=1:n_prof
        if ~isempty(disp_name)
            plot(x,y(:,i),'DisplayName',disp_name(i))
            legend 
        else
            plot(x,y(:,i))
        end
    end
    hold off

    yscale log
    grid on

    if ~isempty(x_lim)
        xlim(x_lim)
    end

    if ~isempty(y_lim)
        ylim(y_lim)
    end

    if ~isempty(x_label)
        xlabel(x_label)
    end

    if ~isempty(y_label)
        ylabel(y_label)
    end

    if ~isempty(title_str)
        title(title_str)
    end
end

